#!/usr/bin/env python3
"""
SUTRA SAM & Neural 3D Asset Reconstruction Pipeline on Kaggle GPU
Project SUTRA — Autonomous Multi-Drone Swarm System (Track SH-DST-05)
Kaggle Dual Tesla T4 / P100 Execution Engine
"""

import sys
import os
import types

# Ensure safe dummy cupy module so einops and pymatting never fail on import
dummy_cupy = types.ModuleType('cupy')
dummy_cupy.ndarray = type('dummy_ndarray', (), {})
dummy_cupy._core = types.ModuleType('cupy._core')
dummy_cupy._core.core = types.ModuleType('cupy._core.core')
sys.modules['cupy'] = dummy_cupy
sys.modules['cupy._core'] = dummy_cupy._core
sys.modules['cupy._core.core'] = dummy_cupy._core.core

import time
import base64
import subprocess

print('=' * 80)
print('  PROJECT SUTRA — SAM & NEURAL 3D ASSET GENERATOR (KAGGLE GPU)')
print('  Track SH-DST-05 | Zero Waste Compute Allocation')
print('=' * 80)

# Step 1: Uninstall broken cupy packages and install TripoSR dependencies
print('')
print('[STEP 1/4] Setting up dependencies & TripoSR...')
subprocess.run([sys.executable, '-m', 'pip', 'uninstall', '-y', 'cupy-cuda12x', 'cupy', 'pymatting'], check=False)
subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', 'numpy<2.0', 'rembg[cpu]', 'trimesh', 'einops', 'omegaconf'], check=True)

tripo_dir = '/tmp/TripoSR'
if not os.path.exists(tripo_dir):
    subprocess.run(['git', 'clone', '--depth', '1', 'https://github.com/VAST-AI-Research/TripoSR.git', tripo_dir], check=True)

if tripo_dir not in sys.path:
    sys.path.insert(0, tripo_dir)

subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', 'git+https://github.com/tatsy/torchmcubes.git'], check=True)

import torch
import trimesh
from PIL import Image
import rembg
from tsr.system import TSR

# Test CUDA kernel compatibility (e.g. sm_60 vs sm_70+)
device = 'cpu'
if torch.cuda.is_available():
    try:
        test_t = torch.zeros(2, 2, device='cuda') + 1.0
        device = 'cuda'
        print(f'PyTorch CUDA verified active: {torch.cuda.get_device_name(0)}')
    except Exception as e:
        print(f'PyTorch CUDA kernel incompatible ({e}), using CPU.')
        device = 'cpu'
else:
    print('CUDA unavailable, using CPU.')

# Step 2: Unpack embedded SAR images
work_dir = '/kaggle/working'
in_dir = os.path.join(work_dir, 'input_images')
out_dir = os.path.join(work_dir, 'sutra_sar_assets')
os.makedirs(in_dir, exist_ok=True)
os.makedirs(out_dir, exist_ok=True)

EMBEDDED_IMAGES = {
    '01_himalayan_house.png': '',
    '02_ndrf_dinghy.jpg': '',
    '03_sar_survivor.jpg': '',
}

for fname, b64 in EMBEDDED_IMAGES.items():
    img_bytes = base64.b64decode(b64)
    out_p = os.path.join(in_dir, fname)
    with open(out_p, 'wb') as f:
        f.write(img_bytes)
    print(f'  [INPUT] Unpacked: {fname} ({len(img_bytes)} bytes)')

# Step 3: Load TripoSR Large Reconstruction Model
print('')
print(f'[STEP 3/4] Initializing TripoSR Large Reconstruction Model on {device}...')
t0 = time.time()
model = TSR.from_pretrained(
    'stabilityai/TripoSR',
    config_name='config.yaml',
    weight_name='model.ckpt'
)
model.renderer.set_chunk_size(8192)
model.to(device)
print(f'Model initialized in {time.time() - t0:.2f}s on {device}')

# Step 4: Run SAM Segmentation & Feedforward 3D Reconstruction
print('')
print('[STEP 4/4] Generating 3D Assets (SAM Segmentation -> Neural 3D Mesh)...')
rembg_session = rembg.new_session()

files = sorted([f for f in os.listdir(in_dir) if f.lower().endswith(('.png', '.jpg', '.jpeg'))])
benchmarks = []

for fname in files:
    in_path = os.path.join(in_dir, fname)
    base_name = os.path.splitext(fname)[0]
    out_glb = os.path.join(out_dir, f'{base_name}.glb')
    out_obj = os.path.join(out_dir, f'{base_name}.obj')

    print(f'Processing: {fname}...')
    t_start = time.time()

    # Step A: SAM Segmentation
    raw_img = Image.open(in_path).convert('RGB')
    nobg_img = rembg.remove(raw_img, session=rembg_session)
    t_sam = time.time() - t_start
    print(f'  [SAM] Alpha segmentation complete ({t_sam:.2f}s)')

    # Step B: Feedforward Neural 3D Reconstruction
    t_3d_start = time.time()
    with torch.no_grad():
        scene_codes = model(nobg_img, device=device)
    mesh = model.extract_mesh(scene_codes, resolution=256)[0]
    t_3d = time.time() - t_3d_start
    print(f'  [3D-LRM] Reconstruction complete ({t_3d:.2f}s)')

    # Step C: Export clean SimReady Meshes (.glb and .obj)
    mesh.export(out_glb)
    mesh.export(out_obj)

    t_total = time.time() - t_start
    v_count = len(mesh.vertices)
    f_count = len(mesh.faces)
    print(f'  [EXPORT] Saved -> {out_glb} ({v_count} verts, {f_count} faces, {t_total:.2f}s total)')

    benchmarks.append({
        'asset': base_name,
        'vertices': v_count,
        'faces': f_count,
        'sam_time_s': round(t_sam, 2),
        'recon_time_s': round(t_3d, 2),
        'total_time_s': round(t_total, 2)
    })

print('')
print('=' * 80)
print('  PROJECT SUTRA — KAGGLE GPU 3D GENERATION BENCHMARKS')
print('=' * 80)
print(f'{"Asset Name":32s} | {"Verts":7s} | {"Faces":7s} | {"SAM (s)":8s} | {"3D (s)":7s} | {"Total":6s}')
print('-' * 80)
for b in benchmarks:
    print(f'{b["asset"]:32s} | {b["vertices"]:7d} | {b["faces"]:7d} | {b["sam_time_s"]:8.2f} | {b["recon_time_s"]:7.2f} | {b["total_time_s"]:5.2f}s')
print('=' * 80)
print(f'All generated 3D assets ready in: {out_dir}')
print('PIPELINE EXECUTION COMPLETE.')
